function numberOfWeeks(milestones) {
  let total = 0;
  let largest = 0;
  for (const count of milestones) {
    total += count;
    largest = Math.max(largest, count);
  }
  const rest = total - largest;
  if (largest <= rest + 1) {
    return total;
  }
  return 2 * rest + 1;
}

