function numberOfWeeks(milestones) {
  // Try every schedule: from each state, pick any project other than last week's that still has work.
  const memo = new Map();
  const longest = (counts, last) => {
    const key = counts.join(',') + '|' + last;
    if (memo.has(key)) return memo.get(key);
    let most = 0;
    for (let i = 0; i < counts.length; i++) {
      if (i === last || counts[i] === 0) continue;
      counts[i]--;
      most = Math.max(most, 1 + longest(counts, i));
      counts[i]++;
    }
    memo.set(key, most);
    return most;
  };
  return longest([...milestones], -1);
}

