function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    // Either balanced projects, or one huge project the others cannot keep up with.
    if (rand() < 0.5) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000000000))];
    const milestones = Array.from({ length: n }, () => 1 + Math.floor(rand() * 200000));
    milestones[Math.floor(rand() * n)] = 1000000000;
    return [milestones];
  }
  const n = 1 + Math.floor(rand() * 4);
  const milestones = Array.from({ length: n }, () => 1 + Math.floor(rand() * 5));
  if (rand() < 0.4) milestones[Math.floor(rand() * n)] = 1 + Math.floor(rand() * 12);
  return [milestones];
}
